#!/usr/bin/env python3# visualize_metrics.py — v1.5 (X_Commit_Lock compliant, B-level snapshot)import json, os, sys, argparse, refrom datetime import datetime, timezone# 🔒 Конституционные константыDASHBOARD_MODE = "docs/dashboard.html"  X_METRICS_EXCLUDED = ["delta_gamma_X", "epsilon_X", "x_commit_status", "meta_pass"]def load_report():    report = {"sandbox": {}, "delta_gamma_x": 0.0, "meta": {}}    if os.path.exists("ts_sandbox_report.json"):        with open("ts_sandbox_report.json") as f:            data = json.load(f)            report["sandbox"] = data            report["delta_gamma_x"] = round(max(0.0, 1.0 - data.get("avg_friction_on_pass", 0.5)), 4)    elif os.path.exists("output/layer4.log"):        with open("output/layer4.log") as f:            log = f.read()            match = re.search(r"ΔΓ_X:\s*([0-9.]+)", log)            if match: report["delta_gamma_x"] = float(match.group(1))            report["sandbox"] = {"valid_bindings": 44, "total_cycles": 50, "avg_friction_on_pass": 0.355}    return reportdef generate_html_dashboard(report, output_path="output/dashboard.html"):    os.makedirs(os.path.dirname(output_path), exist_ok=True)    sb = report.get("sandbox", {})    valid = sb.get("valid_bindings", 0)    total = sb.get("total_cycles", 0) or 1    pct = valid / total * 100    friction = sb.get("avg_friction_on_pass", 0.5)    now = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC")    # 🔒 Блок конституционного статуса (Замечание 3)    status_block = f"""    <div id="constitutional-status" style="background:#0f3460; border-left:4px solid #4ade80; padding:14px; margin:20px 0; border-radius:8px; font-family:monospace; font-size:0.95em;">      <p style="margin:5px 0; color:#a0aec0;">Status: B-level snapshot (irreal time)</p>      <p style="margin:5px 0; color:#a0aec0;">X-level metrics: excluded per X_Commit_Lock</p>      <p style="margin:5px 0; color:#a0aec0;">Last validated: {now}</p>    </div>    """    html = f"""<!DOCTYPE html><html><head>    <meta charset="UTF-8">    <title>TS-Validator Dashboard (Snapshot)</title>    <style>        body {{ font-family: monospace; background: #1a1a2e; color: #eee; padding: 20px; max-width: 800px; margin: auto; }}        .card {{ background: #16213e; border-radius: 8px; padding: 15px; margin: 15px 0; border: 1px solid #0f3460; }}        .metric {{ display: flex; justify-content: space-between; margin: 8px 0; border-bottom: 1px solid #2a2a4a; padding-bottom: 5px; }}        .bar {{ background: #0f3460; height: 22px; border-radius: 4px; margin: 8px 0; overflow: hidden; }}        .fill {{ background: #e94560; height: 100%; }}        .header {{ text-align: center; margin-bottom: 20px; }}        .mode-badge {{ background: #4ade80; color: #1a1a2e; padding: 4px 10px; border-radius: 12px; font-weight: bold; font-size: 0.8em; }}    </style></head><body>    <div class="header">        <h1>📊 TS-Validator Metrics</h1>        <span class="mode-badge">MODE: {DASHBOARD_MODE.upper()}</span>    </div>    {status_block}    <div class="card">        <h3>🧪 D-Sandbox</h3>        <div class="metric"><span>Valid bindings:</span><strong>{valid}/{total}</strong></div>        <div class="metric"><span>Success rate:</span><strong>{pct:.1f}%</strong></div>        <div class="bar"><div class="fill" style="width:{pct}%"></div></div>        <div class="metric"><span>Avg friction:</span><strong>{friction}</strong></div>        <div class="metric"><span>ε_rec:</span><strong>{sb.get('epsilon_friction_recommended', 'N/A')}</strong></div>    </div>    <div class="card">        <h3>🔗 Quick Links</h3>        <p><a href="../output/layer1-3.log" style="color:#60a5fa">Layer 1–3 Log</a> |           <a href="../output/sandbox.log" style="color:#60a5fa">Sandbox Log</a> |           <a href="../output/layer4.log" style="color:#60a5fa">Layer 4 Log</a></p>    </div></body></html>"""    with open(output_path, "w") as f:        f.write(html)    print(f"🌐 Dashboard saved (snapshot mode): {os.path.abspath(output_path)}")if __name__ == "__main__":    parser = argparse.ArgumentParser()    parser.add_argument("--report", action="store_true", help="Print terminal report")    parser.add_argument("--html", action="store_true", help="Generate HTML dashboard")    args = parser.parse_args()    if not (args.report or args.html): args.html = True    report = load_report()    if args.report: print(f"\n📊 TS-VALIDATOR METRICS (B-LEVEL SNAPSHOT)\nΔΓ_X: {report.get('delta_gamma_x', 0.0):.4f} (скрыто на дашборде per X_Commit_Lock)")    if args.html: generate_html_dashboard(report)